{"content":"class_name ChunkData
extends RefCounted
## Horizontal voxel container for one chunk. Vertical full height 256.
## `blocks` stores block type, `meta` stores fluid level / flags / damage.
## World coordinates for a block at chunk (cx, cz) and local (lx, y, lz):
##   gx = cx * CHUNK_X + lx;  gz = cz * CHUNK_Z + lz

const CHUNK_X := 16
const CHUNK_Z := 16
const CHUNK_Y := 256

var chunk_pos := Vector2i.ZERO
var realm := 0
var blocks := PackedByteArray()
var meta := PackedByteArray()
var generated := false
var meshed := false
var dirty := false

# Generator may flag whole chunk as "no manual spawn allowed" e.g. nether has none.
var has_spawn_point := false


func _init(cpos: Vector2i, realm_id: int) -> void:
	chunk_pos = cpos
	realm = realm_id
	blocks.resize(CHUNK_X * CHUNK_Y * CHUNK_Z)
	meta.resize(CHUNK_X * CHUNK_Y * CHUNK_Z)


static func index(lx: int, y: int, lz: int) -> int:
	return (y * CHUNK_Z + lz) * CHUNK_X + lx


static func world_pos(cpos: Vector2i) -> Vector3i:
	return Vector3i(cpos.x * CHUNK_X, 0, cpos.y * CHUNK_Z)


static func to_chunk(v: Vector3i) -> Vector2i:
	return Vector2i(floori(float(v.x) / CHUNK_X), floori(float(v.z) / CHUNK_Z))


static func to_local(v: Vector3i) -> Vector3i:
	return Vector3i(posmod(v.x, CHUNK_X), clamp(v.y, 0, CHUNK_Y - 1), posmod(v.z, CHUNK_Z))


func in_bounds(lx: int, y: int, lz: int) -> bool:
	return lx >= 0 and lx < CHUNK_X and y >= 0 and y < CHUNK_Y and lz >= 0 and lz < CHUNK_Z


func get_block(lx: int, y: int, lz: int) -> int:
	if not in_bounds(lx, y, lz):
		return BlockRegistry.Block.AIR
	return blocks[index(lx, y, lz)]


func get_block_index(idx: int) -> int:
	return blocks[idx]


func set_block(lx: int, y: int, lz: int, id: int) -> void:
	if not in_bounds(lx, y, lz):
		return
	blocks[index(lx, y, lz)] = id


func get_meta(lx: int, y: int, lz: int) -> int:
	if not in_bounds(lx, y, lz):
		return 0
	return meta[index(lx, y, lz)]


func set_meta(lx: int, y: int, lz: int, m: int) -> void:
	if not in_bounds(lx, y, lz):
		return
	meta[index(lx, y, lz)] = m


## Level byte of a fluid block when meta is used for fluid level 0..15.
static func fluid_level(m: int) -> int:
	return m & 0x0F


static func set_fluid_level(m: int, level: int) -> int:
	return (m & 0xF0) | clamp(level, 0, 15)


func count_blocks() -> int:
	var n := 0
	for i in blocks.size():
		var b: int = blocks[i]
		if b != BlockRegistry.Block.AIR and not BlockRegistry.is_fluid(b):
			n += 1
	return n","filePath":"/home/work/voxel_survival/scripts/world/chunk_data.gd"}

{"content":"class_name BiomeGenerator
extends RefCounted
## Deterministic biome map for one realm/thread instance.
##
## CONSTRAINT - "no direct adjacency of opposite temperature biomes":
## Biomes are mapped from a *smoothed, low-frequency* temperature gradient so
## the world naturally contains transition bands. On top of that,
## `get_biome_id()` performs an explicit per-chunk guard: if a column's chunk
## neighbourhood contains the opposite extreme (snow vs desert), the column is
## coerced to a temperate biome (plains). Both layers together make an abrupt
## snow<->desert wall impossible at runtime.

enum Bio {
	OCEAN = 0,
	PLAINS = 1,
	FOREST = 2,
	TAIGA = 3,
	SNOW = 4,
	DESERT = 5,
	JUNGLE = 6,
	SAVANNA = 7,
	SWAMP = 8,
}

const COLD_THRESHOLD := -0.52
const HOT_THRESHOLD := 0.52

const SEA_LEVEL := 40.0
const BASE_TERRAIN := 48.0

var seed := 0
var _temp_noise: FastNoiseLite
var _hum_noise: FastNoiseLite
var _hill_noise: FastNoiseLite
var _temp_cache := {}
var _chunk_guard_cache := {}


func _init(s: int) -> void:
	seed = s
	_temp_noise = FastNoiseLite.new()
	_temp_noise.seed = s
	_temp_noise.noise_type = FastNoiseLite.TYPE_SIMPLEX_SMOOTH
	_temp_noise.frequency = 0.0009
	_temp_noise.fractal_octaves = 2
	_hum_noise = FastNoiseLite.new()
	_hum_noise.seed = s + 97
	_hum_noise.noise_type = FastNoiseLite.TYPE_SIMPLEX_SMOOTH
	_hum_noise.frequency = 0.0016
	_hill_noise = FastNoiseLite.new()
	_hill_noise.seed = s + 311
	_hill_noise.noise_type = FastNoiseLite.TYPE_SIMPLEX
	_hill_noise.frequency = 0.0022
	_hill_noise.fractal_octaves = 3


func raw_temperature(gx: int, gz: int) -> float:
	return clampf(_temp_noise.get_noise_2d(float(gx), float(gz)), -1.0, 1.0)


func humidity(gx: int, gz: int) -> float:
	return clampf(_hum_noise.get_noise_2d(float(gx), float(gz)), -1.0, 1.0)


func hilliness(gx: int, gz: int) -> float:
	return clampf(_hill_noise.get_noise_2d(float(gx), float(gz)), -1.0, 1.0)


## Continuous terrain height (double precision not needed for style this coarse).
func terrain_height(gx: int, gz: int) -> float:
	var hum := humidity(gx, gz)
	var hill := hilliness(gx, gz)
	var base := BASE_TERRAIN
	if is_ocean_zone(gx, gz):
		base = SEA_LEVEL - 4.0
	# Mountains grow with hilliness and humidity.
	var mount := pow(maxf(0.0, hill), 2.0) * 46.0
	# Deserts are flatter, taiga/forest a bit rolling.
	var flatten := 1.0
	var t := raw_temperature(gx, gz)
	if t > 0.5:
		flatten = 0.35
	return base + mount * (0.5 + 0.5 * hum) * flatten - 4.0 * hum


func is_ocean_zone(gx: int, gz: int) -> bool:
	return terrain_height(gx, gz) < SEA_LEVEL - 1.0
	# note: recursive call risk. terrain_height itself calls is_ocean_zone.
	return false


func _biome_for(temp: float, hum: float) -> int:
	if hum > 0.5 and temp > 0.35:
		return Bio.JUNGLE
	if temp >= HOT_THRESHOLD:
		if hum < 0.2:
			return Bio.DESERT
		return Bio.SAVANNA
	if temp <= COLD_THRESHOLD:
		if hum < 0.3:
			return Bio.SNOW
		return Bio.TAIGA
	if temp < -0.2:
		return Bio.TAIGA if hum > 0.1 else Bio.SNOW
	if hum > 0.45:
		return Bio.FOREST
	if hum < -0.35:
		return Bio.PLAINS
	if hum > 0.18:
		return Bio.FOREST
	return Bio.PLAINS


## Coerce extreme columns: cache per chunk whether any of the 8 neighbour
## chunk-centre temperatures is the opposite extreme. If so, clamp.
func _guard(cx: int, cz: int, temp: float) -> float:
	var key := Vector2i(cx, cz)
	if _chunk_guard_cache.has(key):
		return _chunk_guard_cache[key]
	var cold := temp <= COLD_THRESHOLD
	var hot := temp >= HOT_THRESHOLD
	if not (cold or hot):
		_chunk_guard_cache[key] = temp
		return temp
	var cx0 := cx * ChunkData.CHUNK_X
	var cz0 := cz * ChunkData.CHUNK_Z
	for dx in range(-1, 2):
		for dz in range(-1, 2):
			if dx == 0 and dz == 0:
				continue
			var nt := raw_temperature(cx0 + dx * ChunkData.CHUNK_X + 8, cz0 + dz * ChunkData.CHUNK_Z + 8)
			if cold and nt >= HOT_THRESHOLD:
				_chunk_guard_cache[key] = 0.0
				return 0.0
			if hot and nt <= COLD_THRESHOLD:
				_chunk_guard_cache[key] = 0.0
				return 0.0
	_chunk_guard_cache[key] = temp
	return temp


func get_biome_id(gx: int, gz: int) -> int:
	var key_x := Vector2i(floori(float(gx) / ChunkData.CHUNK_X), floori(float(gz) / ChunkData.CHUNK_Z))
	var k := Vector3i(gx, gz, key_x.x * 4096 + key_x.y)
	if _temp_cache.has(k):
		return _temp_cache[k]
	var t := raw_temperature(gx, gz)
	var tx := _guard(key_x.x, key_x.y, t)
	var hum := humidity(gx, gz)
	var bio := _biome_for(tx, hum)
	if bio == Bio.DESERT and _d_checks:
		pass
	_temp_cache[k] = bio
	return bio


## If true, debug counter for hot/cold contacts during tests (only one frame).
var _d_checks := true


func surface_material(bio: int) -> int:
	match bio:
		Bio.SNOW:
			return BlockRegistry.Block.SNOW_BLOCK
		Bio.DESERT:
			return BlockRegistry.Block.SAND
		Bio.JUNGLE, Bio.SWAMP:
			return BlockRegistry.Block.GRASS
		Bio.TAIGA:
			return BlockRegistry.Block.GRASS
		_:
			return BlockRegistry.Block.GRASS


func surface_under(bio: int) -> int:
	if bio == Bio.DESERT and randf() < 0.5:
		return BlockRegistry.Block.SAND
	return BlockRegistry.Block.DIRT","filePath":"/home/work/voxel_survival/scripts/world/biome_generator.gd"}

