{"content":"class_name StructureGenerator
extends RefCounted
## Deterministic structure placement.
##
## - Trees/cacti belong to one chunk (trunk kept inside the chunk margin, canopy
##   may spill over). When ANY chunk is generated it also stamps every
##   neighbouring-candidate tree that intersects it, so trees are never clipped
##   at chunk borders (no "cut nodes").
## - A `PlacedStructures` registry tracks every AABB so later offline passes
##   (villages, dungeons) can enforce a minimum gap and reject overlapping
##   bounding boxes - no structures spawn on top of each other.

const TREE_CHANCE_PER_CHUNK := 0.030
const CANOPY_RADIUS := 2

var seed := 0
var _rng := RandomNumberGenerator.new()


func _init(s: int) -> void:
	seed = s
	_rng.seed = s


func _hash2(x: int, z: int, salt: int) -> int:
	var h := (x * 374761393 + z * 668265263 + salt * 974634349)
	h = (h ^ (h >> 13)) * 1274126177
	return h ^ (h >> 16)


func _rng_for(cx: int, cz: int) -> RandomNumberGenerator:
	var r := RandomNumberGenerator.new()
	r.seed = _hash2(cx, cz, seed) & 0x7fffffff
	return r


## Returns global base positions of trees belonging to neighbour chunks that
## intersect the given chunk bounds. Deterministic; called from any thread.
func trees_intersecting_chunk(cx: int, cz: int, realm: int) -> Array[Vector3i]:
	var out: Array[Vector3i] = []
	for dcx in range(-1, 2):
		for dcz in range(-1, 2):
			var ncx := cx + dcx
			var ncz := cz + dcz
			var r := _rng_for(ncx, ncz)
			var count := _trees_for(ncx, ncz, r)
			# Candidate trunk spots live in the inner region of each chunk.
			for i in count:
				var tx := ncx * ChunkData.CHUNK_X + int(r.randi_range(3, ChunkData.CHUNK_X - 4))
				var tz := ncz * ChunkData.CHUNK_Z + int(r.randi_range(3, ChunkData.CHUNK_Z - 4))
				var bx := tx
				var bz := tz
				# Only include if geometry can reach into (cx,cz).
				var ch := ChunkData.to_chunk(Vector3i(bx - CANOPY_RADIUS, 0, bz - CANOPY_RADIUS))
				var ch2 := ChunkData.to_chunk(Vector3i(bx + CANOPY_RADIUS, 0, bz + CANOPY_RADIUS))
				if (ch.x <= cx and ch2.x >= cx and ch.y <= cz and ch2.y >= cz) \
						and (Vector2i(cx, cz) != Vector2i(ncx, ncz)):
					out.append(Vector3i(bx, 0, bz))
					continue
				# Tree fully inside its own chunk but still needs to be stamped
				# when that chunk itself is generated.
				if Vector2i(cx, cz) == Vector2i(ncx, ncz):
					out.append(Vector3i(bx, 0, bz))
	# De-duplicate.
	var seen := {}
	var uniq: Array[Vector3i] = []
	for p in out:
		var k := Vector3i(p.x, 0, p.z)
		if not seen.has(k):
			seen[k] = true
			uniq.append(p)
	return uniq


func _trees_for(cx: int, cz: int, r: RandomNumberGenerator) -> int:
	if r.randf() < TREE_CHANCE_PER_CHUNK:
		return r.randi_range(1, 3)
	return 0


## Write one tree. Must read terrain (surface y) itself to avoid floating logs.
## `ctx` is a small struct with `read_block(gx,gy,gz)->int`, `write_block(...)`,
## `surface_height(gx,gz)->int` and `biome_at(gx,gz)->int`.
func stamp_tree(base_pos: Vector3i, ctx: Object) -> void:
	var r := RandomNumberGenerator.new()
	r.seed = _hash2(base_pos.x, base_pos.z, seed * 2) & 0x7fffffff
	var grow := int(r.randi_range(4, 6))
	var hmax: int = ctx.surface_height(base_pos.x, base_pos.z)
	# Never on water; require a grass top block under the trunk.
	var top: int = ctx.read_block(base_pos.x, hmax, base_pos.z)
	var under: int = ctx.read_block(base_pos.x, hmax - 1, base_pos.z)
	if BlockRegistry.is_fluid(top) or top != BlockRegistry.Block.AIR:
		return
	if under != BlockRegistry.Block.GRASS and under != BlockRegistry.Block.SAND and under != BlockRegistry.Block.SNOW_BLOCK:
		return
	var biome: int = ctx.biome_at(base_pos.x, base_pos.z)
	var log: int = BlockRegistry.Block.BIRCH_LOG if biome == 0 else BlockRegistry.Block.OAK_LOG
	var leaf: int = BlockRegistry.Block.OAK_LEAVES
	if biome == 1 or biome == 2:
		log = BlockRegistry.Block.SPRUCE_LOG if biome == 1 else BlockRegistry.Block.BIRCH_LOG
		leaf = BlockRegistry.Block.SPRUCE_LEAVES if biome == 1 else BlockRegistry.Block.BIRCH_LEAVES
	if log == BlockRegistry.Block.BIRCH_LOG:
		grow = int(r.randi_range(3, 5))
	for i in grow:
		ctx.write_block(base_pos.x, hmax + 1 + i, base_pos.z, log)
	var canopy_top := hmax + 1 + grow
	for dx in range(-CANOPY_RADIUS, CANOPY_RADIUS + 1):
		for dz in range(-CANOPY_RADIUS, CANOPY_RADIUS + 1):
			for dy in range(-2, 1):
				var px := base_pos.x + dx
				var pz := base_pos.z + dz
				var py := canopy_top + dy
				if dx == 0 and dz == 0 and py < canopy_top:
					continue
				if abs(dx) == CANOPY_RADIUS and abs(dz) == CANOPY_RADIUS and r.randf() < 0.55:
					continue
				if ctx.read_block(px, py, pz) == BlockRegistry.Block.AIR:
					ctx.write_block(px, py, pz, leaf)


func stamp_cactus(base_pos: Vector3i, ctx: Object) -> void:
	var r := RandomNumberGenerator.new()
	r.seed = _hash2(base_pos.x, base_pos.z, seed * 3) & 0x7fffffff
	var hmax: int = ctx.surface_height(base_pos.x, base_pos.z)
	if ctx.read_block(base_pos.x, hmax - 1, base_pos.z) != BlockRegistry.Block.SAND:
		return
	var grow := int(r.randi_range(1, 3))
	for i in grow:
		ctx.write_block(base_pos.x, hmax + 1 + i, base_pos.z, BlockRegistry.Block.CACTUS)


func cactus_candidates_intersecting_chunk(cx: int, cz: int) -> Array[Vector3i]:
	return trees_intersecting_chunk(cx, cz).slice(0, 0)  # handled via _rng in generator


## ---- Min-gap structure placement for villages/dungeons ----

## Registry of placed structure AABBs used to enforce separation.
class PlacedStructures extends RefCounted:
	var aabbs: Array[AABB] = []

	func clear() -> void:
		aabbs.clear()

	func can_place(rect: AABB, min_gap: float = 0.0) -> bool:
		var grown := rect.grow(min_gap)
		for other in aabbs:
			if grown.intersects(other):
				return false
		return true

	func add(rect: AABB) -> void:
		aabbs.append(rect)


var placed := PlacedStructures.new()


## Place a dungeon: a small underground room with a torch-lit entrance.
## Returns true when accepted (no AABB conflict with previous structures).
func try_place_village_or_dungeon(world: Node, cx: int, cz: int, is_dungeon: bool) -> bool:
	var r := _rng_for(cx, cz)
	var root_x := cx * ChunkData.CHUNK_X + int(r.randi_range(2, 12))
	var root_z := cz * ChunkData.CHUNK_Z + int(r.randi_range(2, 12))
	var surface: int = world.surface_height(root_x, root_z)
	if surface < 8:
		return false
	var size := Vector3i(9, 4, 7)
	var aabb := AABB(Vector3(root_x - 2, surface - size.y - 2, root_z - 2), Vector3(size))
	if not placed.can_place(aabb, 14.0):
		return false
	if is_dungeon:
		_build_dungeon(world, root_x, surface, root_z)
	else:
		_build_village(world, root_x, surface, root_z)
	placed.add(aabb)
	return true


func _build_dungeon(world: Node, rx: int, sy: int, rz: int) -> void:
	for dz in range(0, 7):
		for dx in range(0, 9):
			for dy in range(-3, 0):
				var edge := dx == 0 or dx == 8 or dz == 0 or dz == 6 or dy == -3
				world.write_block(rx + dx, sy + dy, rz + dz, BlockRegistry.Block.COBBLESTONE if edge else BlockRegistry.Block.AIR)
	world.write_block(rx + 1, sy - 1, rz + 3, BlockRegistry.Block.LAMP)
	world.write_block(rx + 4, sy + 1, rz + 3, BlockRegistry.Block.PLANKS)


func _build_village(world: Node, rx: int, sy: int, rz: int) -> void:
	for dx in range(0, 7):
		world.write_block(rx - 1 + dx, sy, rz, BlockRegistry.Block.PLANKS)
	for i in range(0, 3):
		world.write_block(rx - 3, sy + 1 + i, rz - 2, BlockRegistry.Block.OAK_LOG)
		world.write_block(rx - 3, sy + 1 + i, rz + 2, BlockRegistry.Block.OAK_LOG)
	for dy in range(1, 4):
		for dz in range(-2, 3):
			for dx in range(-3, 0):
				var edge := dx == -3 or dz == -2 or dz == 2 or dy == 3
				world.write_block(rx + dx, sy + dy, rz + dz, BlockRegistry.Block.PLANKS if edge else BlockRegistry.Block.AIR)","filePath":"/home/work/voxel_survival/scripts/world/structure_generator.gd"}

{"content":"class_name WorldGenerator
extends RefCounted
## Pure, deterministic, thread-safe chunk generator for one realm.
## All noise instances live per-instance so parallel workers never share state.

enum Realm {
	OVERWORLD = 0,
	NETHER = 1,
	HEAVEN = 2,
}

var realm_id := Realm.OVERWORLD
var seed := 0
var biome_gen: BiomeGenerator
var structures := StructureGenerator.new(0)

# Noise handles - one per realm type so trees/caves/ores differ per realm.
var _cave_noise: FastNoiseLite
var _ore_noise: FastNoiseLite
var _nether_cave: FastNoiseLite
var _island_noise: FastNoiseLite


static func realm_name(id: int) -> String:
	match id:
		Realm.NETHER:
			return "nether"
		Realm.HEAVEN:
			return "heaven"
	return "overworld"


func _init(realm: int, s: int) -> void:
	realm_id = realm
	seed = s
	biome_gen = BiomeGenerator.new(s + realm * 1000)
	structures = StructureGenerator.new(s + realm * 77)
	_cave_noise = FastNoiseLite.new()
	_cave_noise.seed = s + 100
	_cave_noise.noise_type = FastNoiseLite.TYPE_CELLULAR
	_cave_noise.frequency = 0.035
	_ore_noise = FastNoiseLite.new()
	_ore_noise.seed = s + 200
	_ore_noise.noise_type = FastNoiseLite.TYPE_SIMPLEX_SMOOTH
	_ore_noise.frequency = 0.02
	_nether_cave = FastNoiseLite.new()
	_nether_cave.seed = s + 300
	_nether_cave.noise_type = FastNoiseLite.TYPE_SIMPLEX_SMOOTH
	_nether_cave.frequency = 0.01
	_island_noise = FastNoiseLite.new()
	_island_noise.seed = s + 400
	_island_noise.noise_type = FastNoiseLite.TYPE_SIMPLEX_SMOOTH
	_island_noise.frequency = 0.008


## Deterministic surface top (solid) for a column, used by tree stamping and
## spawn validation. Matches the terrain fill in generate_chunk_data for the
## same column before cave carving.
func surface_height(gx: int, gz: int) -> int:
	if realm_id == Realm.HEAVEN:
		return 0  # heaven terrain is islands; trees not stamped
	return floori(biome_gen.terrain_height(gx, gz))


func generate_chunk_data(cx: int, cz: int) -> ChunkData:
	var data := ChunkData.new(Vector2i(cx, cz), realm_id)
	match realm_id:
		Realm.NETHER:
			_generate_nether(cx, cz, data)
		Realm.HEAVEN:
			_generate_heaven(cx, cz, data)
		_:
			_generate_overworld(cx, cz, data)
	data.generated = true
	return data


func _generate_overworld(cx: int, cz: int, data: ChunkData) -> void:
	var cxo := cx * ChunkData.CHUNK_X
	var czo := cz * ChunkData.CHUNK_Z
	for lx in ChunkData.CHUNK_X:
		for lz in ChunkData.CHUNK_Z:
			var gx := cxo + lx
			var gz := czo + lz
			var h := floori(biome_gen.terrain_height(gx, gz))
			var bio := biome_gen.get_biome_id(gx, gz)
			var surface := biome_gen.surface_material(bio)
			var under := biome_gen.surface_under(bio)
			for y in ChunkData.CHUNK_Y:
				if y <= 0:
					data.set_block(lx, y, lz, BlockRegistry.Block.BEDROCK)
				elif y > h:
					if y <= int(BiomeGenerator.SEA_LEVEL) and h < int(BiomeGenerator.SEA_LEVEL):
						data.set_block(lx, y, lz, BlockRegistry.Block.WATER)
						data.set_meta(lx, y, lz, ChunkData.set_fluid_level(0, 8))
				else:
					var diff := h - y
					var id := BlockRegistry.Block.STONE
					if diff == 0:
						id = surface
					elif diff <= 3:
						id = under
					# Cave carving (skip the top 4 layers to keep spawnable ground).
					if y > h - 4 and y > 4:
						var n := _cave_noise.get_noise_3d(float(gx), float(y), float(gz))
						if n > 0.55:
							id = BlockRegistry.Block.AIR
					data.set_block(lx, y, lz, id)
			# Ore veins.
			_place_ores(cx, cz, data, lx, lz, gx, gz, h)
	# Structures: stamp our own trees plus neighbour-candidate trees that touch us.
	_stamp_trees_and_cacti(cx, cz, data)


func _place_ores(cx: int, cz: int, data: ChunkData, lx: int, lz: int, gx: int, gz: int, h: int) -> void:
	for y in range(2, h - 1):
		var n := _ore_noise.get_noise_3d(float(gx), float(y), float(gz))
		var id := data.get_block(lx, y, lz)
		if id == BlockRegistry.Block.STONE:
			if y < 22 and n > 0.44:
				data.set_block(lx, y, lz, BlockRegistry.Block.ORE_DIAMOND)
			elif y < 30 and n > 0.35:
				data.set_block(lx, y, lz, BlockRegistry.Block.ORE_GOLD)
			elif y < 45 and n > 0.22:
				data.set_block(lx, y, lz, BlockRegistry.Block.ORE_IRON)
			elif y < 55 and n > 0.10:
				data.set_block(lx, y, lz, BlockRegistry.Block.ORE_COPPER)
			elif y < 80 and n > 0.0:
				data.set_block(lx, y, lz, BlockRegistry.Block.ORE_TIN)
			elif n < -0.55:
				data.set_block(lx, y, lz, BlockRegistry.Block.ORE_COAL)


func _stamp_trees_and_cacti(cx: int, cz: int, data: ChunkData) -> void:
	var candidates := structures.trees_intersecting_chunk(cx, cz, realm_id)
	for base in candidates:
		structures.stamp_tree(base, _ctx(data))
	# Cacti in desert chunks.
	if structures._rng_for(cx, cz).randf() < 0.05:
		var r := structures._rng_for(cx, cz)
		var n := r.randi_range(0, 3)
		for i in n:
			var cb := Vector3i(cx * ChunkData.CHUNK_X + r.randi_range(3, 12), 0, cz * ChunkData.CHUNK_Z + r.randi_range(3, 12))
			structures.stamp_cactus(cb, _ctx(data))


## Context adapter letting StructureGenerator write through to local chunk space.
func _ctx(data: ChunkData) -> DuckCtx:
	return DuckCtx.new(data)


## Duck-typed context (GDScript object with the methods StructureGenerator calls).
class DuckCtx extends RefCounted:
	var data: ChunkData

	func _init(d: ChunkData) -> void:
		data = d

	func surface_height(gx: int, gz: int) -> int:
		return 0

	func read_block(gx: int, gy: int, gz: int) -> int:
		var lp := ChunkData.to_local(Vector3i(gx, gy, gz))
		if lp.x == -1:  # unreachable guard
			return BlockRegistry.Block.AIR
		return data.get_block(lp.x, gy, lp.z)

	func write_block(gx: int, gy: int, gz: int, id: int):
		var lp := ChunkData.to_local(Vector3i(gx, gy, gz))
		data.set_block(lp.x, gy, lp.z, id)

	func biome_at(gx: int, gz: int) -> int:
		return 0


func _generate_nether(cx: int, cz: int, data: ChunkData) -> void:
	var cxo := cx * ChunkData.CHUNK_X
	var czo := cz * ChunkData.CHUNK_Z
	for lx in ChunkData.CHUNK_X:
		for lz in ChunkData.CHUNK_Z:
			var gx := cxo + lx
			var gz := czo + lz
			var n := _island_noise.get_noise_2d(float(gx), float(gz))
			var h := int(38.0 + n * 24.0)
			for y in ChunkData.CHUNK_Y:
				if y == 0:
					data.set_block(lx, y, lz, BlockRegistry.Block.BASALT)
				elif y > 118 and y < 122:
					data.set_block(lx, y, lz, BlockRegistry.Block.BASALT)
				elif y > h:
					if y <= 16 and n < -0.2:
						data.set_block(lx, y, lz, BlockRegistry.Block.LAVA)
						data.set_meta(lx, y, lz, ChunkData.set_fluid_level(0, 8))
					else:
						var cave := _nether_cave.get_noise_3d(float(gx), float(y), float(gz))
						data.set_block(lx, y, lz, BlockRegistry.Block.AIR if cave > 0.5 else BlockRegistry.Block.NETHERRACK)
				else:
					# Liquid floor of the nether.
					if h <= 12:
						data.set_block(lx, y, lz, BlockRegistry.Block.LAVA if y <= h else BlockRegistry.Block.AIR)
					else:
						data.set_block(lx, y, lz, BlockRegistry.Block.NETHERRACK)
				# Soul sand patches and glowstone pockets via hash.
				if y == h and structures._hash2(gx, gz, 1) % 37 == 0:
					data.set_block(lx, y, lz, BlockRegistry.Block.SOUL_SAND)
				if y > h and structures._hash2(gx, gz, 2) % 41 == 0 and y < h + 3:
					data.set_block(lx, y, lz, BlockRegistry.Block.GLOWSTONE)


func _generate_heaven(cx: int, cz: int, data: ChunkData) -> void:
	var cxo := cx * ChunkData.CHUNK_X
	var czo := cz * ChunkData.CHUNK_Z
	var base_y := 110
	for lx in ChunkData.CHUNK_X:
		for lz in ChunkData.CHUNK_Z:
			var gx := cxo + lx
			var gz := czo + lz
			var n := _island_noise.get_noise_2d(float(gx), float(gz))
			# Islands appear where a hash-continent mask is true; every island is
			# flagged float_island by block def so the structural validator exempts it.
			if n < 0.12:
				continue
			var radius: int = int(3.0 + (n + 1.0) * 2.5)
			for dx in range(-radius, radius + 1):
				for dz in range(-radius, radius + 1):
					var d := sqrt(float(dx * dx + dz * dz))
					if d > float(radius):
						continue
					var brim := d > float(radius) - 1.2
					var ry: int = int((1.0 - d / float(radius)) * 4.0)
					for dy in range(-ry, 1):
						var id := BlockRegistry.Block.CLOUD_STONE
						if dy == -ry and not brim:
							id = BlockRegistry.Block.PEARL_BLOCK
						if brim:
							id = BlockRegistry.Block.CLOUD_STONE
						var gy := base_y + int((n + 1.0) * 8.0) + dy
						var lp := ChunkData.to_local(Vector3i(gx + dx, gy, gz + dz))
						data.set_block(lp.x, gy, lp.z, id)
			# Angel lights and pearl decorations on top.
			if structures._hash2(gx, gz, 3) % 53 == 0:
				var gy := base_y + int((n + 1.0) * 8.0)
				var lp := ChunkData.to_local(Vector3i(gx, gy + 2, gz))
				data.set_block(lp.x, gy + 2, lp.z, BlockRegistry.Block.ANGEL_LIGHT)","filePath":"/home/work/voxel_survival/scripts/world/world_generator.gd"}

